import React, { useState, useEffect, useRef } from 'react';
import styles from './TerminalCursor.module.css';

const TerminalCursor = () => {
  const [position, setPosition] = useState({ x: -100, y: -100 });
  const [isHovering, setIsHovering] = useState(false);
  const [isTouchDevice, setIsTouchDevice] = useState(false);
  const lensRef = useRef(null);

  useEffect(() => {
    if ('ontouchstart' in window || navigator.maxTouchPoints > 0) {
      setIsTouchDevice(true);
      return;
    }

    const handleMouseMove = (e) => {
      setPosition({ x: e.clientX, y: e.clientY });
      
      // Update lens position for CSS custom properties
      document.documentElement.style.setProperty('--cursor-x', `${e.clientX}px`);
      document.documentElement.style.setProperty('--cursor-y', `${e.clientY}px`);
    };

    const handleMouseEnter = () => setIsHovering(true);
    const handleMouseLeave = () => setIsHovering(false);

    window.addEventListener('mousemove', handleMouseMove);
    document.body.addEventListener('mouseenter', handleMouseEnter);
    document.body.addEventListener('mouseleave', handleMouseLeave);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      document.body.removeEventListener('mouseenter', handleMouseEnter);
      document.body.removeEventListener('mouseleave', handleMouseLeave);
    };
  }, []);

  if (isTouchDevice) return null;

  return (
    <>
      <div 
        className={`${styles.portalLens} ${isHovering ? styles.active : ''}`}
        style={{
          left: position.x,
          top: position.y,
        }}
      >
        <div className={styles.lensInner}>
          <div className={styles.portalGlow}></div>
          <div className={styles.scanLines}></div>
          <div className={styles.glitchOverlay}></div>
          <div className={styles.lensRing}></div>
        </div>
      </div>
      
      {/* Hidden dimension content that appears inside lens */}
      <div className={styles.alternateDimension}>
        <div className={styles.dimensionText}>// ACCESSING MATRIX</div>
        <div className={styles.dimensionText}>>_ SYSTEM BREACH</div>
        <div className={styles.dimensionText}>⚡ CYBERPUNK MODE</div>
        <div className={styles.dimensionGlow}></div>
      </div>
    </>
  );
};

export default TerminalCursor;
